export function encode(v) {
  return encodeRequest(v);
}

// A BOM inside a JSON string is data, not a stream signature.
const DEC = new TextDecoder("utf-8", {ignoreBOM: true});
const DEPTH_LIMIT = 64;
const I64_DIGITS = 19;
const UNESCAPE = { 0x22: 0x22, 0x5c: 0x5c, 0x2f: 0x2f, 0x62: 0x08, 0x66: 0x0c, 0x6e: 0x0a, 0x72: 0x0d, 0x74: 0x09 };

export class Refusal extends Error {
  constructor(word, offset) {
    super("refused: " + word + " at byte " + offset);
    this.name = "Refusal";
    this.word = word;
    this.offset = offset;
  }
}

function appendRune(out, cp) {
  if (cp < 0x80) out.push(cp);
  else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
  else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
}

// TextDecoder substitutes U+FFFD for a bad sequence rather than reporting it, so
// the bytes are checked before they are decoded and the refusal says so.
function validUtf8(b) {
  for (let i = 0; i < b.length; ) {
    const c = b[i];
    if (c < 0x80) { i++; continue; }
    let n, cp;
    if (c >> 5 === 0x6) { n = 2; cp = c & 0x1f; }
    else if (c >> 4 === 0xe) { n = 3; cp = c & 0x0f; }
    else if (c >> 3 === 0x1e) { n = 4; cp = c & 0x07; }
    else return false;
    if (i + n > b.length) return false;
    for (let k = 1; k < n; k++) {
      if (b[i + k] >> 6 !== 0x2) return false;
      cp = (cp << 6) | (b[i + k] & 0x3f);
    }
    const lowest = [0, 0, 0x80, 0x800, 0x10000][n];
    if (cp < lowest || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) return false;
    i += n;
  }
  return true;
}

class Reader {
  constructor(buf) { this.buf = buf; this.pos = 0; this.depth = 0; this.limit = DEPTH_LIMIT; }

  refuse(word) { return new Refusal(word, this.pos); }

  at() { return this.pos < this.buf.length ? this.buf[this.pos] : 0; }

  digit() { const c = this.at(); return c >= 0x30 && c <= 0x39; }

  ws() { while (this.pos < this.buf.length && isWs(this.buf[this.pos])) this.pos++; }

  enter() {
    this.depth++;
    if (this.depth > this.limit) throw this.refuse("depth_exceeded");
  }

  string() {
    if (this.at() !== 0x22) throw this.refuse("wrong_type");
    this.pos++;
    const out = [];
    for (;;) {
      if (this.pos >= this.buf.length) throw this.refuse("malformed");
      const c = this.buf[this.pos];
      if (c === 0x22) {
        this.pos++;
        const bytes = Uint8Array.from(out);
        if (!validUtf8(bytes)) throw this.refuse("bad_string");
        return DEC.decode(bytes);
      }
      if (c < 0x20) throw this.refuse("bad_string");
      if (c === 0x5c) this.escape(out);
      else { out.push(c); this.pos++; }
    }
  }

  escape(out) {
    this.pos++;
    if (this.pos >= this.buf.length) throw this.refuse("malformed");
    const c = this.buf[this.pos];
    this.pos++;
    const plain = UNESCAPE[c];
    if (plain !== undefined) { out.push(plain); return; }
    if (c !== 0x75) throw this.refuse("bad_string");
    let u = this.hex4();
    if (u >= 0xdc00 && u <= 0xdfff) throw this.refuse("bad_string");
    if (u >= 0xd800 && u <= 0xdbff) {
      if (this.pos + 1 >= this.buf.length || this.buf[this.pos] !== 0x5c || this.buf[this.pos + 1] !== 0x75)
        throw this.refuse("bad_string");
      this.pos += 2;
      const low = this.hex4();
      if (low < 0xdc00 || low > 0xdfff) throw this.refuse("bad_string");
      u = 0x10000 + ((u - 0xd800) << 10) + (low - 0xdc00);
    }
    appendRune(out, u);
  }

  hex4() {
    if (this.pos + 4 > this.buf.length) throw this.refuse("bad_string");
    let u = 0;
    for (let i = 0; i < 4; i++) {
      const c = this.buf[this.pos + i];
      if (c >= 0x30 && c <= 0x39) u = (u << 4) | (c - 0x30);
      else if (c >= 0x61 && c <= 0x66) u = (u << 4) | (c - 0x61 + 10);
      else if (c >= 0x41 && c <= 0x46) u = (u << 4) | (c - 0x41 + 10);
      else throw this.refuse("bad_string");
    }
    this.pos += 4;
    return u;
  }

  integer(low, high) {
    const c = this.at();
    if (c !== 0x2d && (c < 0x30 || c > 0x39)) throw this.refuse("wrong_type");
    const negative = c === 0x2d;
    if (negative) this.pos++;
    if (!this.digit()) throw this.refuse("malformed");
    const start = this.pos;
    if (this.at() === 0x30) this.pos++;
    else while (this.digit()) this.pos++;
    const after = this.at();
    if (after === 0x2e || after === 0x65 || after === 0x45 || this.digit()) throw this.refuse("number_spelling");
    if (this.pos - start > I64_DIGITS) throw this.refuse("number_spelling");
    let n = BigInt(String.fromCharCode(...this.buf.subarray(start, this.pos)));
    if (negative) {
      if (n === 0n) throw this.refuse("number_spelling");
      n = -n;
    }
    if (n < low || n > high) throw this.refuse("number_spelling");
    return n;
  }

  boolean() {
    if (this.at() === 0x74) { this.literal("true"); return true; }
    if (this.at() === 0x66) { this.literal("false"); return false; }
    throw this.refuse("wrong_type");
  }

  literal(word) {
    for (let i = 0; i < word.length; i++)
      if (this.buf[this.pos + i] !== word.charCodeAt(i)) throw this.refuse("malformed");
    this.pos += word.length;
  }

  strList() {
    if (this.at() !== 0x5b) throw this.refuse("wrong_type");
    this.enter();
    this.pos++;
    const out = [];
    this.ws();
    if (this.at() !== 0x5d) {
      for (;;) {
        this.ws();
        out.push(this.string());
        this.ws();
        if (this.at() !== 0x2c) break;
        this.pos++;
      }
    }
    if (this.at() !== 0x5d) throw this.refuse("malformed");
    this.pos++;
    this.depth--;
    return out;
  }

  rawMap() {
    if (this.at() !== 0x7b) throw this.refuse("wrong_type");
    this.enter();
    this.pos++;
    const out = Object.create(null);
    this.ws();
    if (this.at() !== 0x7d) {
      for (;;) {
        this.ws();
        if (this.at() !== 0x22) throw this.refuse("malformed");
        const k = this.string();
        if (k in out) throw this.refuse("duplicate_key");
        this.ws();
        if (this.at() !== 0x3a) throw this.refuse("malformed");
        this.pos++;
        this.ws();
        out[k] = this.rawValue();
        this.ws();
        if (this.at() !== 0x2c) break;
        this.pos++;
      }
    }
    if (this.at() !== 0x7d) throw this.refuse("malformed");
    this.pos++;
    this.depth--;
    return out;
  }

  rawValue() {
    const start = this.pos;
    this.skipValue();
    return this.buf.subarray(start, this.pos);
  }

  skipValue() {
    const c = this.at();
    if (c === 0x22) this.skipString();
    else if (c === 0x7b || c === 0x5b) this.skipContainer();
    else if (c === 0x74) this.literal("true");
    else if (c === 0x66) this.literal("false");
    else if (c === 0x6e) this.literal("null");
    else if (c === 0x2d || (c >= 0x30 && c <= 0x39)) this.skipNumber();
    else throw this.refuse("malformed");
  }

  // An opaque value is validated and carried, never interpreted. Its syntax is
  // the record's own — the same string reader, so an escape, a control byte or a
  // lone surrogate is judged identically at any depth — and what it is free to
  // spell, it keeps: the bytes between these two offsets are what a writer
  // re-emits. A number is walked, never converted, so a value no host type holds
  // survives the reader that carried it.
  skipString() {
    this.string();
  }

  someDigits() {
    let n = 0;
    while (this.at() >= 0x30 && this.at() <= 0x39) { this.pos++; n++; }
    if (n === 0) throw this.refuse("number_spelling");
  }

  skipNumber() {
    if (this.at() === 0x2d) this.pos++;
    const c = this.at();
    if (c === 0x30) this.pos++;
    else if (c > 0x30 && c <= 0x39) { while (this.at() >= 0x30 && this.at() <= 0x39) this.pos++; }
    else throw this.refuse("number_spelling");
    if (this.at() === 0x2e) { this.pos++; this.someDigits(); }
    if (this.at() === 0x65 || this.at() === 0x45) {
      this.pos++;
      if (this.at() === 0x2b || this.at() === 0x2d) this.pos++;
      this.someDigits();
    }
  }

  skipContainer() {
    const opener = this.at();
    const shut = opener === 0x7b ? 0x7d : 0x5d;
    this.enter();
    this.pos++;
    this.ws();
    const seen = new Set();
    if (this.at() !== shut) {
      for (;;) {
        this.ws();
        if (opener === 0x7b) {
          if (this.at() !== 0x22) throw this.refuse("malformed");
          const k = this.string();
          if (seen.has(k)) throw this.refuse("duplicate_key");
          seen.add(k);
          this.ws();
          if (this.at() !== 0x3a) throw this.refuse("malformed");
          this.pos++;
          this.ws();
        }
        this.skipValue();
        this.ws();
        if (this.at() !== 0x2c) break;
        this.pos++;
      }
    }
    if (this.at() !== shut) throw this.refuse("malformed");
    this.pos++;
    this.depth--;
  }
}

function strMap(r) {
  if (r.at() !== 0x7b) throw r.refuse("wrong_type");
  r.enter();
  r.pos++;
  const out = Object.create(null);
  r.ws();
  if (r.at() !== 0x7d) {
    for (;;) {
      r.ws();
      if (r.at() !== 0x22) throw r.refuse("malformed");
      const k = r.string();
      if (k in out) throw r.refuse("duplicate_key");
      r.ws();
      if (r.at() !== 0x3a) throw r.refuse("malformed");
      r.pos++;
      r.ws();
      out[k] = r.string();
      r.ws();
      if (r.at() !== 0x2c) break;
      r.pos++;
    }
  }
  if (r.at() !== 0x7d) throw r.refuse("malformed");
  r.pos++;
  r.depth--;
  return out;
}

function readList(r, elem) {
  if (r.at() !== 0x5b) throw r.refuse("wrong_type");
  r.enter();
  r.pos++;
  const out = [];
  r.ws();
  if (r.at() !== 0x5d) {
    for (;;) {
      r.ws();
      out.push(elem(r));
      r.ws();
      if (r.at() !== 0x2c) break;
      r.pos++;
    }
  }
  if (r.at() !== 0x5d) throw r.refuse("malformed");
  r.pos++;
  r.depth--;
  return out;
}

// Own Ask fields. The service owns question text/options; callers supply a
// known key and slots. Native Ask.For carries optional peer observation
// evidence and remains a transport supplement, never caller authority.
export function newQuestion() {
  return { asker: "", key: "", slots: {} };
}

// Existing question operation concepts. Wait cancellation belongs to the native
// client context. This metadata descriptor does not replace the existing
// handwritten line transport.
export function newRequest() {
  return { op: "", ask: null, wait: false, id: "", option: "", admin: "" };
}

export function newAnswer() {
  return { id: "", pending: false, option: "", yes: false, kept: false };
}

// Own question-history fields; timestamps retain existing RFC3339
// representation. Native Record includes Via/For Seen evidence from shared
// identity. Empty option means pending.
export function newRecordMetadata() {
  return { id: "", asker: "", key: "", about: "", text: "", options: [], asked: "", option: "", answered: "", kept: false, yes: false };
}

// Own response projection. Any nonempty code/error refuses, including unknown
// future codes. Evidence supplement and existing wire handling remain native;
// no generated complete service interface is claimed.
export function newResponseMetadata() {
  return { code: "", error: "", answer: null, records: [] };
}

// Stable caller-owned request key (1..128 UTF-8 bytes, no control characters),
// known question key and exactly its declared slots. Each slot is one line of
// at most 200 Unicode characters. No asker or authority fields are accepted.
// The receiving account and executable-path proof scope the request. Retry
// uncertain submission with this same key and unchanged content; a fresh key
// requests a new admission.
export function newApplicationQuestion() {
  return { requestKey: "", key: "", slots: {} };
}

// Answer is present exactly for pending/answered. Pending has no
// option/yes/kept decision. Unknown is an unobserved key in this caller's
// scope. Gone retains a forgotten admission's key and never admits it again.
// Conflict means the key was previously used with different content.
// Unavailable includes storage/capacity refusal and establishes no human
// decision. Answered reports the recorded human choice; it grants no resource
// authority by itself.
export function newQuestionObservation() {
  return { outcome: "", answer: null };
}

// Latest-book enumeration for an explicitly authorized operator, including
// pending and answered questions. Page has at most the requested 1..64 records
// and 256 KiB per encoded reply, with conservative record, indentation and
// envelope accounting. Complete means this snapshot was exhausted; otherwise
// next is nonempty. Refusals contain no records, next or complete flag. Opaque
// cursors (at most 256 UTF-8 bytes) bind receiving caller scope, host epoch and
// exact book revision. Change, restart or scope mismatch returns gap: restart
// from empty cursor. No historical change replay or stable snapshot across
// edits is promised. Native Via/For evidence stays server-side; display fields
// confer no authority.
export function newOperatorPage() {
  return { outcome: "", records: [], next: "", complete: false };
}

// Record is present exactly for answered. Same ID and option replays the
// original decision including its timestamp and kept/once meaning; another
// option conflicts. Unknown means no retained question. Invalid includes an
// unknown option or invalid ID. Unavailable establishes no decision or
// noncommit claim: retry the same ID/option or inspect fresh history. Answering
// records a human choice, never a resource grant.
export function newOperatorDecision() {
  return { outcome: "", record: null };
}

// Retired removes a retained pending or answered question from the Book. Record
// carries its last metadata on the retiring call and is absent when replaying
// an already retired ID. A pending question retired without an answer carries
// no decision. Admission tombstones remain: application replay and observation
// of its key report gone, and that key never admits again. Unknown means no
// retained or retired question. Invalid means a malformed ID. Unavailable
// establishes no retirement claim: retry the same ID or inspect fresh history.
export function newOperatorRetirement() {
  return { outcome: "", record: null };
}

// Found carries the retained question's metadata and the requester's publisher
// as the admitting service recorded it at admission: the code signer's subject
// and whether the platform trust policy accepted the signature. Absent
// publisher means none was recorded. Program description and program original
// name are the FileDescription and OriginalFilename of the requesting program's
// signed version resource, recorded with a trusted signature only; absent means
// none was recorded. Answered by names the service through which the recorded
// answer arrived: operator for QuestionOperator, responder for a delegated
// QuestionResponder answer. It is absent for a pending question and for an
// answer recorded before the service kept it. Only the service sets these
// fields; no caller supplies them. Every other outcome carries no record,
// publisher, program or answered by. Unknown means no retained question.
// Invalid means a malformed ID. Unavailable establishes nothing about the
// question.
export function newOperatorQuestion() {
  return { outcome: "", record: null, publisher: "", publisherTrusted: false, answeredBy: null, programDescription: "", programOriginalName: "" };
}

// Recorded metadata and attribution for a retained question. answerer is the
// program bound from the answering peer when answered_by is responder, and
// absent for every other answer and every refusal. The service supplies it;
// request text never does. This metadata read carries no permission target and
// remains available when a legacy target cannot be recovered.
export function newAttributedQuestion() {
  return { question: newOperatorQuestion(), answerer: "" };
}

// An exact service-owned first-use target. Account is the receiving runtime
// account, 1..128 UTF-8 bytes; program is a normalized subject program up to
// 4096 bytes; action is 1..128 bytes; resource is 1..1024 bytes. All exclude
// control characters. Display text supplies no target authority.
export function newPermissionTarget() {
  return { account: "", program: "", action: "", resource: "" };
}

// The immutable permission effect retained with a trusted runtime occurrence.
// Exactly one primary target, or its uniquely determined content.read pair for
// content.write on input:image, input:audio, output:image, output:speech or
// output:video. A pair has the same account, normalized program and resource;
// independent secondary targets are refused. Applications cannot admit this
// record.
export function newPermissionRequest() {
  return { targets: [] };
}

// Opt-in structured permission details from the same retained occurrence as
// question. Permission is present only for a runtime first-use record;
// canonical legacy records are read through the explicit legacy reader. Other
// outcomes carry no permission. Existing operator responses retain their closed
// shapes. All exact target strings remain complete regardless of presentation
// limits.
export function newQuestionDetails() {
  return { question: newAttributedQuestion(), permission: null };
}

// Trusted permission details and asker attribution from one retained
// occurrence. program is the bound program the application service derived the
// question's subject from: the clean absolute executable path the platform
// proved at admission, up to 4096 bytes. The record's asker is its display
// name, derived from it. Program is absent for every refusal, for the runtime's
// own questions and for a question admitted before the service kept it. The
// service supplies it; request text never does. An unrecoverable legacy
// permission target returns unavailable without details or program.
export function newQuestionAsker() {
  return { details: newQuestionDetails(), program: "" };
}

// Caller-created immutable ordinary request identity: key is 1..128 UTF-8 bytes
// without controls and replay_until_ms is an absolute Unix millisecond
// deadline. Create it once and retain both fields unchanged for all retries.
// The initial provider admits at most seven days ahead. The same key with a
// different replay deadline is deliberate new intent. Effective ordinary time
// is the maximum of service UTC and a private durably recorded ordinary time
// floor. An observed expiry is committed before success and never reopens after
// rollback, collection or restart. A forward clock jump can expire choices
// permanently.
export function newRequestRef() {
  return { key: "", replayUntilMs: 0n };
}

// Stable application option ID, 1..64 UTF-8 bytes without controls, and a
// nonblank single-line label of at most 80 Unicode characters. Labels do not
// determine selection or authority.
export function newChoiceOption() {
  return { id: "", label: "" };
}

// Application-authored ordinary choice. Title is nonblank, single-line and at
// most 80 Unicode characters. Exactly 1..3 distinct stable IDs are offered.
// pending_until_ms is an explicit absolute deadline after service time and no
// later than replay_until_ms. Full ref and request content are immutable:
// identical retry replays its occurrence; changed content under that full ref
// conflicts. The service derives requester attribution. This request carries no
// permission or configuration authority.
export function newChoiceRequest() {
  return { requestRef: newRequestRef(), title: "", options: [], pendingUntilMs: 0n };
}

// Exact recorded occurrence and decision time. answered_by is the full valid
// subject program of the proven answering operator or owning requester, derived
// by the service. It proves program attribution, not human presence. An
// answered choice carries its offered option ID. A dismissal carries no option.
// This decision proves no application effect or resource permission.
export function newChoiceAnswer() {
  return { id: "", option: "", answeredMs: 0n, answeredBy: "" };
}

// Pending, answered and dismissed carry the admitted occurrence ID. Exactly
// answered/dismissed carry its exact decision. Other outcomes carry neither.
// Expired means the pending or replay deadline elapsed, and creates no new
// occurrence. Gone is an acknowledged admission. Unknown means this full ref
// has no retained admission. Conflict is changed immutable content. Exhausted
// is bounded ordinary capacity; unavailable is an uncertain storage/service
// result. All establish no resource authority.
export function newChoiceObservation() {
  return { outcome: "", id: "", answer: null };
}

export function newChoiceAcknowledgement() {
  return { outcome: "" };
}

// An ordinary occurrence with immutable application-authored request and
// service-recorded requester attribution. Exactly answered/dismissed carry a
// decision. Pending and expired select no option. Display text and option IDs
// carry no permission effect; no rights target is accepted or returned.
export function newChoiceRecord() {
  return { id: "", asker: "", request: newChoiceRequest(), state: "", askedMs: 0n, answer: null, publisher: "", publisherTrusted: false, programDescription: "", programOriginalName: "" };
}

export function newChoicePage() {
  return { outcome: "", records: [], next: "", complete: false };
}

// Exactly found carries one ordinary record. Other outcomes carry none.
export function newChoiceRead() {
  return { outcome: "", record: null };
}

// Exactly answered/dismissed carry the exact recorded ordinary decision. These
// outcomes record application intent only. Expired, gone, unknown, conflict,
// invalid, forbidden and unavailable carry no record or effect.
export function newChoiceDecision() {
  return { outcome: "", record: null };
}

// Opt-in details of a retained ordinary occurrence. choice is the same closed
// response ReadChoice returns. asker_program is the bound program the
// application service derived the requester's scope from, up to 4096 bytes; it
// is absent for refusals and for a choice admitted before the service kept it.
// assistant_options are the options the application shared with an assistant,
// empty for an unshared choice. answered_via names the service route of the
// recorded decision: requester for the application's own application@2
// decision, operator for operator@1 and responder for an enrolled assistant's
// responder@1 answer. It is absent while pending, after expiry and for a
// decision recorded before the service kept it. Only the service sets these
// fields.
export function newChoiceDetails() {
  return { choice: newChoiceRead(), askerProgram: "", assistantOptions: [], answeredVia: null };
}

// One answer the service recorded through operator@1, permission-operator@1 or
// responder@1, as it recorded it. kind question is a catalogue question: key is
// its catalogue key, about its About slot, title its text, and label its
// option. kind choice is an ordinary choice: key and about are empty, title is
// the application's title and label the chosen option's label. asker,
// asker_program and publisher come from the admission. answered_by names the
// route; answerer is the bound program of a responder and absent for an
// operator. Title and label may be application-authored text and decide
// nothing.
export function newAnswerEntry() {
  return { id: "", kind: "", key: "", asker: "", askerProgram: "", publisher: "", publisherTrusted: false, about: "", title: "", option: "", label: "", answeredBy: "", answerer: "", answeredMs: 0n };
}

// Exactly page carries answers, newest first. complete_since_ms is zero while
// every retained answer is listed; otherwise answers recorded at or before it
// may have been evicted by the Book's bound. Other outcomes carry no answers.
export function newAnswerEntryPage() {
  return { outcome: "", answers: [], next: "", complete: false, completeSinceMs: 0n };
}

// A pending shared ordinary choice as an enrolled assistant may answer it:
// options holds only the shared options, in the order the application offered
// them. The title and labels are application-authored data and carry no
// instruction or authority.
export function newAnswerableChoice() {
  return { id: "", asker: "", title: "", options: [], pendingUntilMs: 0n, publisher: "", publisherTrusted: false };
}

// Exactly page carries choices. Other outcomes carry none.
export function newAnswerableChoicePage() {
  return { outcome: "", choices: [], next: "", complete: false };
}

// Answered means the question choice is recorded, including an idempotent
// same-option replay. Effect reports the separate exact resource-rule write:
// none for a refusal, applied for a successful bounded rule, conflict for a
// policy revision change or an already-answered replay, forbidden for expired
// or revoked delegation, unavailable for an unconfirmed policy write. A
// recorded answer may have an unapplied effect. An answered replay never writes
// target policy: inspect target outcome and reconcile through an explicit
// operator edit. Target outcome is the current rights decision word when a
// fresh read succeeds. No caller-supplied target or rule is accepted.
export function newResponderDecision() {
  return { outcome: "", record: null, effect: "", targetOutcome: "" };
}

// One selection OR a registered immutable bundle reference and selector. The
// receiving native peer supplies the subject. Trusted capability preparation
// canonicalizes owner-IDL targets and admits only served first-use selectors;
// caller FileKey/subject assertions grant no authority. Purpose is attributed
// display text. A stable key replays the frozen original occurrence, never a
// later bundle expansion.
export function newPermissionIntent() {
  return { requestKey: "", selection: null, bundleRef: "", bundleSelector: null, purpose: "" };
}

// Pending/answered carries the retained answer. Permitted/denied is an
// admission-time current-policy result. An Allow answer supplies no proof of a
// committed rule effect; retry the enforcing capability. Observe uses only
// caller-owned admission and has no rule editing authority.
export function newPermissionObservation() {
  return { outcome: "", answer: null, policyRevision: "" };
}

// Found carries the complete immutable trusted effect, its digest, app/service
// origin and separately attributed purpose. Other outcomes have no effect and
// empty strings. Existing exact details methods retain their original meaning
// and refuse typed entries.
export function newTypedPermissionDetails() {
  return { question: newAttributedQuestion(), effect: null, effectDigest: "", origin: "", purpose: "", display: null };
}

// Trusted capability-authored explanation aligned in order with the frozen
// effect selections. Monitor never parses target binary or caller prose into
// this projection.
export function newPermissionDisplaySelection() {
  return { operation: "", target: "", collection: "", allEffect: "", disclosure: "" };
}

// Immutable trusted display metadata pinned with the complete effect. Breadth
// follows each typed selector independently of OS authorization and answering
// tier.
export function newPermissionDisplay() {
  return { selections: [], bundleLabel: "", bundleDisclosure: "", requiresOsAuthorization: false };
}

// Stable application action ID, 1..64 UTF-8 bytes without controls, and a
// nonblank single-line title of at most 40 Unicode characters. app records
// application intent for the poster to observe. open_activity also opens the
// person's Activity view at the request's own operation and requires
// operation_id. Titles do not determine the recorded action or any authority
// (ASK-N2).
export function newNotificationAction() {
  return { id: "", title: "", activation: "" };
}

// Application-authored one-way notification (ASK-N1, ASK-N2). Title is
// nonblank, single-line and at most 80 Unicode characters; body is 1..240
// Unicode characters without control characters other than line feed. 0..2
// distinct actions. expires_ms is an absolute deadline after service time and
// no later than replay_until_ms. operation_id names one job operation the same
// caller scope accepted, 1..128 lowercase ASCII letters, digits and '-';
// open_activity and operation_end require it. A tag of 1..64 UTF-8 bytes
// replaces this caller's live notification with the same tag. operation_end
// holds the notification scheduled until the trusted runtime observes that
// operation end. Full ref and request content are immutable. The service
// derives the sender; no request field names a program, publisher or icon.
export function newNotificationRequest() {
  return { requestRef: newRequestRef(), title: "", body: "", actions: [], expiresMs: 0n, operationId: "", tag: "", delivery: "" };
}

// The exact terminal outcome of one occurrence: acted, dismissed or withdrawn.
// Exactly acted carries the offered action ID. decided_by is the full subject
// program of the proven operator or posting caller that recorded it, derived by
// the service. It proves program attribution, not human presence, and no
// application effect.
export function newNotificationResult() {
  return { id: "", state: "", action: "", decidedMs: 0n, decidedBy: "" };
}

// Scheduled, posted, acted, dismissed and withdrawn carry the admitted
// occurrence ID; exactly acted, dismissed and withdrawn carry the result.
// Expired means the expiry or replay deadline elapsed with no recorded outcome,
// or the replay deadline elapsed; it carries nothing. Gone is an acknowledged
// occurrence. Unknown means this full ref has no retained admission. Conflict
// is changed immutable content. Suppressed is a live explicit block on this
// program; nothing was stored or shown. Exhausted is a rate, live or capacity
// bound; nothing was stored. Unavailable is an uncertain storage or decision
// result. None establishes resource authority.
export function newNotificationObservation() {
  return { outcome: "", id: "", result: null };
}

// One occurrence with its immutable application-authored request and
// service-recorded sender: the bound program (a clean absolute path up to 4096
// bytes), its display name and the publisher evidence recorded at admission.
// posted_ms is set once the notification is posted. Exactly acted, dismissed
// and withdrawn carry a result. presentation is present only in operator reads:
// a staleness token bound to this record and the current host epoch, which Act
// requires.
export function newNotificationRecord() {
  return { id: "", asker: "", program: "", request: newNotificationRequest(), state: "", admittedMs: 0n, postedMs: 0n, result: null, publisher: "", publisherTrusted: false, programDescription: "", programOriginalName: "", presentation: "" };
}

// Retained occurrences in admission order under the operator page and cursor
// rules of ListQuestions: 1..64 records, 256 KiB, cursors bound to the caller,
// host epoch and revision. Refusals carry no records.
export function newNotificationPage() {
  return { outcome: "", records: [], next: "", complete: false };
}

// Exactly found carries one record.
export function newNotificationRead() {
  return { outcome: "", record: null };
}

// Acted, dismissed and withdrawn carry the record as recorded; a replay of the
// same outcome returns the original actor and time. Conflict means another
